            right_knee: preds[0].keypoints[14],
            right_shoulder: preds[0].keypoints[6],
            right_wrist: preds[0].keypoints[10],
        }

        self.postMessage({preds: keypoints, canvasWidth: canvas.width, canvasHeight: canvas.height})
    }
})

